function h(e){e?.classList.add("has-results")}function g(e){e?.classList.remove("has-results")}function f(e){e?.replaceChildren()}function t(e){return String(e??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}function p(e){return String(e??"").replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}function u(e){return String(e??"").trim().toLowerCase()}function x(e,o){let r=String(e??""),n=u(o);if(n==="")return t(r);let l=n.split(/\s+/).filter(Boolean).map(p);if(l.length===0)return t(r);let c=new RegExp(`(${l.join("|")})`,"ig");return r.split(c).map((s,i)=>{let a=t(s);return i%2===1?`<mark class="search-highlight">${a}</mark>`:a}).join("")}export{t as a,u as b,x as c,h as d,g as e,f};
